.cs-progress-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  margin-left: 8px;
  background: rgba(37, 99, 235, 0.12);
  color: var(--text, #0f172a);
  border-radius: 10px;
  border: 1px solid rgba(37, 99, 235, 0.35);
  font-size: 0.8rem;
}

.cs-progress-chip::before {
  content: '☑️';
}

.cs-progress-chip[data-complete='true'] {
  background: rgba(34, 197, 94, 0.14);
  border-color: rgba(34, 197, 94, 0.5);
}

js:
(function() {
  'use strict';

  const api = window.CardSpoke?.utils;

  function calculateProgress(text) {
    if (!text) return { total: 0, done: 0 };
    const matches = text.match(/\[( |x|X)\]/g) || [];
    const done = matches.filter((m) => m.toLowerCase() === '[x]').length;
    return { total: matches.length, done };
  }

  function renderChip(container, progress) {
    if (!container) return;
    const existing = container.querySelector('.cs-progress-chip');
    if (existing) existing.remove();

    if (progress.total === 0) return;

    const chip = document.createElement('span');
    chip.className = 'cs-progress-chip';
    chip.dataset.complete = progress.done === progress.total ? 'true' : 'false';
    chip.textContent = `${progress.done}/${progress.total} done`;
    container.appendChild(chip);
  }

  function enhanceCards() {
    const cards = document.querySelectorAll('.card, .card-detail');
    cards.forEach((card) => {
      const header = card.querySelector('.card-header, .card-detail-header, .card-title');
      const body = card.querySelector('.card-body, .card-detail-body');
      if (!header || !body) return;
      const progress = calculateProgress(body.textContent || '');
      renderChip(header, progress);
    });
  }

  const observer = new MutationObserver(() => setTimeout(enhanceCards, 60));
  observer.observe(document.body, { childList: true, subtree: true });
  enhanceCards();

  api?.showToast('Checklist Progress Plugin active', 'success');
})();
